package com.stacklab.config;
import com.stacklab.entity.*;import com.stacklab.repository.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.context.annotation.Profile;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;
@Component @Profile({"dev","demo"}) public class DemoDataSeeder implements ApplicationRunner{
 private final UserRepository users;private final ProjectRepository projects;private final TaskRepository tasks;private final NotificationRepository notifications;private final ActivityRepository activities;private final PasswordEncoder encoder;@Value("${app.demo.seed-password:}")private String seedPassword;
 public DemoDataSeeder(UserRepository u,ProjectRepository p,TaskRepository t,NotificationRepository n,ActivityRepository a,PasswordEncoder e){users=u;projects=p;tasks=t;notifications=n;activities=a;encoder=e;}
 @Override @Transactional public void run(ApplicationArguments args){if(seedPassword==null||seedPassword.length()<12||users.existsByEmailIgnoreCase("admin@stacklab.local"))return;
 AppUser admin=users.save(new AppUser("Stacklab Admin","admin@stacklab.local",encoder.encode(seedPassword),Role.ADMIN));AppUser manager=users.save(new AppUser("Maya Manager","maya@stacklab.local",encoder.encode(seedPassword),Role.MANAGER));AppUser employee=users.save(new AppUser("Eli Employee","eli@stacklab.local",encoder.encode(seedPassword),Role.EMPLOYEE));AppUser employee2=users.save(new AppUser("Sam Employee","sam@stacklab.local",encoder.encode(seedPassword),Role.EMPLOYEE));Project p=projects.save(new Project("Demo Platform","Seeded demo project",manager));Instant now=Instant.now();Task late=tasks.save(new Task("Resolve overdue alert","Seed example overdue task",employee,p,now.minusSeconds(3600),Priority.HIGH,TaskStatus.IN_PROGRESS));tasks.save(new Task("Review API design","Awaiting review",employee2,p,now.plusSeconds(86400),Priority.MEDIUM,TaskStatus.REVIEW));tasks.save(new Task("Complete onboarding","Finished sample",employee,p,now.minusSeconds(3600),Priority.LOW,TaskStatus.COMPLETED));tasks.save(new Task("Implement dashboard","Active work sample",employee2,p,now.plusSeconds(172800),Priority.CRITICAL,TaskStatus.TO_DO));notifications.save(new Notification(employee,late,"You have been assigned task: "+late.getTitle()));activities.save(new ActivityLog(null,p,admin,"PROJECT_CREATED",null,null,p.getName()));activities.save(new ActivityLog(late,p,manager,"TASK_CREATED",null,null,late.getTitle()));}
}
